<?php require 'functions.php';if(user())go('index.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$err='Isi nama, email valid, dan password minimal 8 karakter.';else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'pelanggan')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Registrasi berhasil. Silakan masuk.');go('login.php');}catch(PDOException $e){$err='Email sudah digunakan atau registrasi gagal.';}}}$pageTitle='Daftar';require 'header.php';?><section class="auth"><h1>Buat akun pelanggan</h1><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?><form method="post" class="form-card"><?=csrf_field()?><label>Nama lengkap<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (minimal 8 karakter)<input type="password" name="password" required minlength="8"></label><button class="btn">Daftar</button></form><p>Sudah punya akun? <a href="<?=url('login.php')?>">Masuk</a></p></section><?php require 'footer.php';?>